  entry: srcPath + "/index.ts",
  output: {
    path: tmpPath,
    filename: "qr-code-styling.js",
    globalObject: "this",
    library: "QRCodeStyling",
    libraryTarget: "umd",
    libraryExport: "default"
  },
  module: {
    rules: [
      {
        test: /\.ts$/,
        loader: "ts-loader",
        exclude: /node_modules/
      }
    ]
  },
  plugins: [
    new ESLintPlugin(),
    new FileManagerPlugin({
      events: {
        onEnd: {
          copy: [{ source: tmpPath + "/**/*", destination: libPath }],
          delete: [tmpPath]
        }
